const utcSeconds=value=>new Date(value===undefined?Date.now():value).toISOString().replace(/\.\d{3}Z$/,'Z');
function tokenTime(value){if(value===null||value===undefined)return null;let text=String(value);if(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(text))text=text.replace(' ','T')+':00+08:00';return utcSeconds(text);}
