function checkDeletion(){const d=CP.deletion,page=assetReferencePage({refresh:true});d.expectedCurrentVersion=page.currentVersion;d.checked=true;d.error='';d.message=page.totalReferences?'全部版本仍有 '+page.totalReferences+' 处引用，无法删除。':'全部版本没有引用，可删除整个资产及其版本。';return page;}
function deleteAsset(){const d=CP.deletion;if(!d.checked)throw Error('请先检查当前版本及引用。');if(d.expectedCurrentVersion!==d.currentVersion)throw Error('资产版本已改变；请重新检查引用。');if(d.totalReferences)throw Error('资产仍被引用，不能删除；请先在引用对象中解除依赖。');d.output={assetId:d.assetId,deleted:true,removedVersionCount:d.versionCount,contentCleanup:'deferred'};d.message='资产及其全部版本已删除。';return clone(d.output);}
const settingMeta={'storage.runRetentionEnabled':{name:'自动清理运行记录',values:[false,true],labels:['关闭自动清理','开启自动清理'],activation:'immediate'},'storage.observationRetentionEnabled':{name:'自动清理观察记录',values:[false,true],labels:['关闭自动清理','开启自动清理'],activation:'immediate'},'ui.theme':{name:'界面主题',values:['system','light','dark'],labels:['跟随系统','浅色','深色'],activation:'immediate'},'runtime.interruptPolicy':{name:'物理操作接管策略',values:['pause','ignore'],labels:['暂停运行','忽略普通操作'],activation:'nextRun'},'agent.previewHz':{name:'录制预览频率',activation:'restartAgent'}};
function validSettingValue(schema,value){if(schema.oneOf)return schema.oneOf.filter(sc=>validSettingValue(sc,value)).length===1;if(schema.enum&&!schema.enum.some(v=>JSON.stringify(v)===JSON.stringify(value)))return false;if(schema.const!==undefined&&JSON.stringify(schema.const)!==JSON.stringify(value))return false;if(schema.type){const matches=schema.type==='null'?value===null:schema.type==='integer'?Number.isSafeInteger(value):schema.type==='number'?typeof value==='number'&&Number.isFinite(value):schema.type==='array'?Array.isArray(value):schema.type==='object'?value!==null&&typeof value==='object'&&!Array.isArray(value):typeof value===schema.type;if(!matches)return false;}if(typeof value==='number'&&(schema.minimum!==undefined&&value<schema.minimum||schema.maximum!==undefined&&value>schema.maximum))return false;if(typeof value==='string'&&(schema.minLength!==undefined&&value.length<schema.minLength||schema.maxLength!==undefined&&value.length>schema.maxLength))return false;if(value&&typeof value==='object'&&!Array.isArray(value)&&schema.properties){if((schema.required||[]).some(k=>!Object.hasOwn(value,k)))return false;for(const [key,item]of Object.entries(value)){if(!Object.hasOwn(schema.properties,key)){if(schema.additionalProperties===false)return false;}else if(!validSettingValue(schema.properties[key],item))return false;}}return true;}
function saveSettings(){const x=CP.settings;if(x.version!==x.expectedVersion||x.baseVersion!==x.expectedBaseVersion)throw Error('设置或继承来源已更新；本批编辑未保存，请重新读取并核对。');const updates=Object.entries(x.draft).map(([key,v])=>({op:v.op,key,...(v.op==='set'?{value:v.value}:{})}));const changes=[];for(const u of updates){const definition=settingsDefinitions.find(d=>d.key===u.key);if(!definition)throw Error('设置键未登记。');if(!definition.scopes.includes(x.scope))throw Error('该设置只能在当前用户范围修改。');if(!['set','reset'].includes(u.op))throw Error('设置操作只能为设置覆盖或恢复继承。');if(u.op==='set'&&!validSettingValue(definition.valueSchema,u.value))throw Error(definition.label+'的值不在合法范围。');const changed=u.op==='reset'?Object.hasOwn(x.overrides,u.key):!Object.hasOwn(x.overrides,u.key)||JSON.stringify(x.overrides[u.key])!==JSON.stringify(u.value);changes.push({key:u.key,activation:definition.activation,changed});}
 const next={values:clone(x.values),overrides:clone(x.overrides),sources:clone(x.sources),pending:clone(x.pending)};const changed=changes.filter(c=>c.changed),nextVersion=x.version+(changed.length?1:0);for(const u of updates){if(!changes.find(c=>c.key===u.key).changed)continue;if(u.op==='reset'){delete next.overrides[u.key];next.values[u.key]=clone(x.inherited[u.key]);next.sources[u.key]=x.scope==='workspace'&&Object.hasOwn(CP.settingsLayers?.user?.overrides||{},u.key)?'user':'default';}else{next.overrides[u.key]=clone(u.value);next.values[u.key]=clone(u.value);next.sources[u.key]=x.scope;}next.pending=next.pending.filter(p=>p.key!==u.key);if(settingsDefinitions.find(d=>d.key===u.key).activation==='restartAgent')next.pending.push({key:u.key,activation:'restartAgent',savedVersion:nextVersion});}
 const activations=[...new Set(changed.map(c=>c.activation))],activation=activations.length>1?'mixed':activations[0]||'immediate';Object.assign(x,next);x.version=nextVersion;x.expectedVersion=nextVersion;x.result={snapshot:{scope:x.scope,version:x.version,baseVersion:x.baseVersion,values:clone(x.values),overrides:clone(x.overrides),sources:clone(x.sources),pending:clone(x.pending)},activation,changes};x.message=changed.length?'整批设置已保存；各项按所示时间生效。':'设置值保持不变，没有新增待生效项。';x.draft={};x.formDraft={};x.cleanupConfirmed=false;return clone(x.result);}
function bridgeSnapshot(){const b=CP.bridge;return clone({savedVersion:b.savedVersion,savedConfig:b.savedConfig,activeVersion:b.activeVersion,activeConfig:b.activeConfig,requiresRestart:b.requiresRestart,state:b.state});}
function updateStamp(u){return JSON.stringify([u.channel,u.candidateVersion,u.targetSha256,u.keyId,u.rootVersion,u.revocationsVersion,u.metadataSequence,u.targetSequence,u.minimumSafeSequence,u.backupId]);}
function checkUpdateTrust(u){if(!u.clockValid)throw Error('系统日期或时间不正确，请修正后重试。');if(!u.trustAvailable)throw Error('无法读取更新验证信息，请重新获取安装包。');if(Date.now()>=u.metadataExpiresAt)throw Error('更新信息已过期，请重新检查更新。');if(u.revoked)throw Error('此更新包已撤回，请选择其他版本。');if(u.metadataSequence<u.highestSequence)throw Error('更新信息不是最新版本，请重新检查更新。');if(u.targetSequence<u.minimumSafeSequence)throw Error('该版本不符合最低安全版本要求，不能安装。');if(!u.metadataValid)throw Error('更新信息签名无效，请重新检查更新。');if(!u.keyTrusted||!u.rotationVerified)throw Error('无法确认更新包的发布者，请重新获取安装包。');if(!u.packageValid)throw Error('更新包校验失败，请重新下载完整安装包。');}
function invalidateUpdate(u,error){u.result=null;u.downgradePlan=null;u.verifiedStamp=null;u.state='failed';throw error;}
function verifyUpdate(){const u=CP.update;try{checkUpdateTrust(u);}catch(error){invalidateUpdate(u,error);}u.state='verified';u.verifiedStamp=updateStamp(u);u.highestSequence=Math.max(u.highestSequence,u.metadataSequence);u.error='';u.message='安装包校验通过，可以继续安装。';return {verified:true,channel:u.channel,version:u.candidateVersion,keyId:u.keyId};}
function prepareUpdate(){const u=CP.update;try{checkUpdateTrust(u);}catch(error){invalidateUpdate(u,error);}if(!['verified','preparing'].includes(u.state))throw Error('请先完成更新校验。');if(u.verifiedStamp!==updateStamp(u))invalidateUpdate(u,Error('安装包或所选版本已改变，请重新检查。'));const parts=u.candidateVersion.split('.').map(Number),installed=u.installedVersion.split('.').map(Number);let downgrade=false;for(let i=0;i<3;i++){if(parts[i]!==installed[i]){downgrade=parts[i]<installed[i];break;}}if(downgrade&&(!u.allowDowngrade||!u.localConfirmed))throw Error('降级需要在本机明确确认，并检查当前数据的兼容与备份。');if(u.downgradePlan&&Date.now()>=u.downgradePlan.expiresAt)invalidateUpdate(u,Error('降级确认已过期，请重新校验并准备新的确认。'));if(u.result)return clone(u.result);if(downgrade)u.downgradePlan={sourceVersion:u.installedVersion,targetVersion:u.candidateVersion,targetSha256:u.targetSha256,channel:u.channel,targetSequence:u.targetSequence,rootVersion:u.rootVersion,revocationsVersion:u.revocationsVersion,backupId:u.backupId,expiresAt:Date.now()+600000,confirmationGrant:'host-downgrade-confirmation'};u.result={channel:u.channel,version:u.candidateVersion,prepared:true,downgrade,...(downgrade?{plan:clone(u.downgradePlan)}:{})};u.state='preparing';u.message='已进入安装准备：先保存草稿、停止运行、释放输入并检查备份。';return clone(u.result);}
